def compute_gcd(a: int, b: int) -> int:
    if a == 0:
        return b
    elif b == 0:
        return a
    while True:
        if a > b:
            a %= b
        else:
            b %= a
        if a == 0 or b == 0:
            break
    return max(a, b)
```

