def longest_consecutive_streak(items: list[int]) -> int:
    if not items:
        return 0

    sorted_items = sorted(set(items))
    longest_streak = 1
    current_streak = 1

    for i in range(1, len(sorted_items)):
        if sorted_items[i] == sorted_items[i - 1] + 1:
            current_streak += 1
        else:
            longest_streak = max(longest_streak, current_streak)
            current_streak = 1

