import ast

def matches_filter(expression: str, record: dict) -> bool:
    try:
        # Create an abstract syntax tree from the expression
        node = ast.parse(expression, mode='eval').body

        # Define a visitor class to replace variables with their corresponding values from the record
        class FilterVisitor(ast.NodeTransformer):
            def visit_Name(self, node):
                if node.id in record:
                    return ast.copy_location(
                        ast.NameConstant(value=record[node.id]), node)
                else:
                    raise ValueError(f"Invalid variable name: {node.id}")

        # Replace variables in the AST with their corresponding values
        node = FilterVisitor().visit(node)

        # Evaluate the modified AST
        return eval(compile(node, filename="<ast>", mode="eval"))

    except (SyntaxError, NameError, ValueError) as e:
        raise ValueError("Invalid filter expression") from e
```

