import re

def is_allowed_webhook(url: str) -> bool:
    # Check if the URL starts with 'http' or 'https'
    if not url.lower().startswith('https'):
        return False

    # Check for backslashes, spaces, or control characters in the URL
    if any(char in url for char in r'\x00-\x1F\x7F'):
        return False

    # Extract the host part of the URL
    host = url.split('//')[1].split('/')[0]

    # Check if the host ends with a dot
    if host.endswith('.'):
        host = host[:-1]

    # Split the host by dots and validate each label
    labels = host.split('.')
    if len(labels) < 2 or labels[-1] == '':
        return False

    for label in labels:
        if not re.match(r'^[a-zA-Z0-9-]+$', label):
            return False
        if '-' in label and label[-1] == '-':
            return False

    # Check if the last label contains only letters
    if not re.match(r'^[a-zA-Z]+$', labels[-1]):
        return False

    # Check if the host is 'localhost' or ends with '.localhost'
    if host.lower() in ['localhost', 'localhost.']:
        return False

    # Check if there is a port and if it is not 443
    if ':' in host and int(host.split(':')[1]) != 443:
        return False

    return True
