from collections import deque

def count_shortest_paths(n: int, edges: list[tuple[int, int]], source: int, target: int) -> int:
    if source == target:
        return 1

    # Build the adjacency list for the graph
    adj_list = [[] for _ in range(n)]
    for u, v in edges:
        adj_list[u].append(v)
        adj_list[v].append(u)

    # Initialize the queue for BFS and visited array
    queue = deque([source])
    visited = [False] * n
    visited[source] = True

    # Dictionary to store the number of paths to each node
    path_count = {source: 1}

    while queue:
        current = queue.popleft()

        for neighbor in adj_list[current]:
            if not visited[neighbor]:
                visited[neighbor] = True
                queue.append(neighbor)

                # If this is the first time we visit the neighbor, copy the path count from the current node
                if neighbor not in path_count:
                    path_count[neighbor] = path_count[current]
                else:
                    # If we have already visited the neighbor, add the path count from the current node to it
                    path_count[neighbor] += path_count[current]

    # Return the number of shortest paths to the target node
    return path_count.get(target, 0)
```

