from math import gcd
from functools import reduce

def lcm(a: int, b: int) -> int:
    return abs(a*b) // gcd(a, b)

def solve_congruences(congruences: list[tuple[int, int]]) -> tuple[int, int] | None:
    if not congruences:
        return (0, 1)

    def chinese_remainder_theorem(a_values: list[int], n_values: list[int]) -> tuple[int, int]:
        sum = 0
        prod = reduce(lcm, n_values)

        for n_i, a_i in zip(n_values, a_values):
            p = prod // n_i
            sum += a_i * mod_inverse(p, n_i) * p

        return sum % prod, prod

    def mod_inverse(a: int, m: int) -> int:
        m0, x0, x1 = m, 0, 1
        if m == 1:
            return 0
        while a > 1:
            # q is quotient
            q = a // m
            m, a = a % m, m
            x0, x1 = x1 - q * x0, x0
        # Make x1 positive
        if x1 < 0:
            x1 += m0
        return x1

    a_values = [r for r, _ in congruences]
    n_values = [m for _, m in congruences]

    return chinese_remainder_theorem(a_values, n_values)
```

