def convert_base(number: str, from_base: int, to_base: int) -> str:
    if not number or number == '-' or any(char not in '0123456789abcdefghijklmnopqrstuvwxyz' for char in number):
        raise ValueError("Invalid input")

    # Remove leading zeros
    number = number.lstrip('0')

    # Convert from from_base to decimal
    if number[0] == '-':
        is_negative = True
        number = number[1:]
    else:
        is_negative = False

    decimal_value = 0
    for char in number:
        if '0' <= char <= '9':
            value = ord(char) - ord('0')
        else:
            value = ord(char) - ord('a') + 10

        if value >= from_base:
            raise ValueError("Invalid digit in number")

        decimal_value = decimal_value * from_base + value

    # Convert from decimal to to_base
    if decimal_value == 0:
        return '0'

    result = []
    while decimal_value > 0:
        remainder = decimal_value % to_base
        if remainder < 10:
            result.append(str(remainder))
        else:
            result.append(chr(remainder - 10 + ord('a')))
        decimal_value //= to_base

    if is_negative:
        result.insert(0, '-')

    return ''.join(result[::-1])
```

