def free_slots(busy: list[tuple[int, int]], day_start: int, day_end: int, min_len: int) -> list[tuple[int, int]]:
    if day_start >= day_end:
        return []

    # Sort the busy times by their start time
    busy.sort()

    free = []
    current_free_start = day_start

    for start, end in busy:
        if start < current_free_start:
            continue  # Overlapping with previous busy slot

        if end - current_free_start >= min_len:
            free.append((current_free_start, end))

        current_free_start = max(current_free_start, end)

    # Check the remaining free space after the last busy slot
    if day_end > current_free_start and day_end - current_free_start >= min_len:
        free.append((current_free_start, day_end))

    return free
