def tokenize_code(source: str) -> list[tuple[str, str]]:
    if not source.strip():
        return []

    tokens = []
    i = 0

    while i < len(source):
        char = source[i]

        if char.isdigit():
            j = i + 1
            while j < len(source) and source[j].isdigit():
                j += 1
            if j < len(source) and source[j] == '.':
                k = j + 1
                while k < len(source) and source[k].isdigit():
                    k += 1
                tokens.append(('NUMBER', source[i:k]))
                i = k
            else:
                tokens.append(('NUMBER', source[i:j]))
                i = j
        elif char.isalpha() or char == '_':
            j = i + 1
            while j < len(source) and (source[j].isalnum() or source[j] == '_'):
                j += 1
            tokens.append(('NAME', source[i:j]))
            i = j
        elif char in '+-*/<>=(),':
            tokens.append(('OP', char))
            i += 1
        elif char in ' \t\n':
            i += 1
        else:
            raise ValueError(f"Invalid character '{char}' at position {i}")

    return tokens
