def run_stack_machine(program: list[str]) -> list[int]:
    stack = []
    ip = 0  # Instruction Pointer

    while ip < len(program):
        instruction = program[ip].split()
        op = instruction[0]

        if len(instruction) > 1:
            arg = int(instruction[1])

        if op == 'PUSH':
            stack.append(arg)
        elif op == 'POP':
            if not stack:
                raise ValueError("Stack underflow")
            stack.pop()
        elif op == 'DUP':
            if not stack:
                raise ValueError("Stack underflow")
            stack.append(stack[-1])
        elif op == 'SWAP':
            if len(stack) < 2:
                raise ValueError("Not enough elements on stack for SWAP")
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif op == 'ADD':
            if len(stack) < 2:
                raise ValueError("Not enough elements on stack for ADD")
            stack.append(stack.pop() + stack.pop())
        elif op == 'SUB':
            if len(stack) < 2:
                raise ValueError("Not enough elements on stack for SUB")
            stack.append(-stack.pop() + stack.pop())
        elif op == 'MUL':
            if len(stack) < 2:
                raise ValueError("Not enough elements on stack for MUL")
            stack.append(stack.pop() * stack.pop())
        elif op == 'JMP':
            ip = arg - 1
        elif op == 'JZ':
            if not stack:
                raise ValueError("Stack underflow")
            if stack.pop() == 0:
                ip = arg - 1
        elif op == 'HALT':
            break
        else:
            raise ValueError(f"Unknown operation: {op}")

        ip += 1

    return stack[::-1]
