def run_stack_machine(program: list[str]) -> list[int]:
    stack = []
    ip = 0
    max_instructions = 1000

    while ip < len(program):
        if len(stack) > 1000:
            raise ValueError("Stack overflow")

        instruction = program[ip].split()
        op = instruction[0]

        if op == 'PUSH':
            n = int(instruction[1])
            stack.append(n)
        elif op == 'POP':
            if not stack:
                raise ValueError("Stack underflow")
            stack.pop()
        elif op == 'DUP':
            if not stack:
                raise ValueError("Stack underflow")
            stack.append(stack[-1])
        elif op == 'SWAP':
            if len(stack) < 2:
                raise ValueError("Not enough elements on stack for swap")
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif op == 'ADD':
            if len(stack) < 2:
                raise ValueError("Not enough elements on stack for addition")
            b = stack.pop()
            a = stack.pop()
            stack.append(a + b)
        elif op == 'SUB':
            if len(stack) < 2:
                raise ValueError("Not enough elements on stack for subtraction")
            b = stack.pop()
            a = stack.pop()
            stack.append(a - b)
        elif op == 'MUL':
            if len(stack) < 2:
                raise ValueError("Not enough elements on stack for multiplication")
            b = stack.pop()
            a = stack.pop()
            stack.append(a * b)
        elif op == 'JMP':
            t = int(instruction[1])
            if t >= len(program):
                raise ValueError("Jump target out of bounds")
            ip = t - 1
        elif op == 'JZ':
            if not stack:
                raise ValueError("Stack underflow")
            if stack[-1] == 0:
                t = int(instruction[1])
                if t >= len(program):
                    raise ValueError("Jump target out of bounds")
                ip = t - 1
        elif op == 'HALT':
            break

        ip += 1
        max_instructions -= 1
        if max_instructions <= 0:
            raise RuntimeError("Maximum number of instructions exceeded")

    return stack
