def run_bank_ops(balances: dict[str, int], ops: list[tuple]) -> tuple[dict[str, int], list[int]]:
    final_balances = balances.copy()
    failed = []

    for i, op in enumerate(ops):
        action, *args = op

        if action == 'deposit':
            account, amount = args
            if account not in final_balances or amount <= 0:
                failed.append(i)
                continue
            final_balances[account] += amount

        elif action == 'withdraw':
            account, amount = args
            if account not in final_balances or amount <= 0 or final_balances[account] < amount:
                failed.append(i)
                continue
            final_balances[account] -= amount

        elif action == 'transfer':
            source, target, amount = args
            fee = 2
            if source not in final_balances or target not in final_balances or amount <= 0 or final_balances[source] < amount + fee:
                failed.append(i)
                continue
            final_balances[source] -= (amount + fee)
            final_balances[target] += amount

        elif action == 'freeze':
            account, = args
            if account not in final_balances:
                failed.append(i)
                continue

        elif action == 'unfreeze':
            account, = args
            if account not in final_balances:
                failed.append(i)
                continue

        else:
            failed.append(i)

    return final_balances, failed[::-1]
